import{_ as a,o as l,c as r,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"2017 Ceph社区年度进展报告","description":"","frontmatter":{"title":"2017 Ceph社区年度进展报告","date":"2017-12-01T00:00:00.000Z","updated":"2017-12-01T00:00:00.000Z","tags":["Ceph","社区动态","年度报告"],"categories":["年度总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2017/2017_Ceph社区年度总结.md","filePath":"posts/2017/2017_Ceph社区年度总结.md","lastUpdated":1780460162000}'),i={name:"posts/2017/2017_Ceph社区年度总结.md"};function h(t,e,_,s,n,m){return l(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="ceph-2017-年社区年度进展报告" tabindex="-1">Ceph 2017 年社区年度进展报告 <a class="header-anchor" href="#ceph-2017-年社区年度进展报告" aria-label="Permalink to &quot;Ceph 2017 年社区年度进展报告&quot;">​</a></h1><hr><h2 id="一、全年技术演进概述" tabindex="-1">一、全年技术演进概述 <a class="header-anchor" href="#一、全年技术演进概述" aria-label="Permalink to &quot;一、全年技术演进概述&quot;">​</a></h2><p>2017 年是 Ceph 项目技术架构发生重大转变的一年。全年的技术主线围绕三个核心方向展开：<strong>BlueStore 存储后端的成熟与 GA</strong>、<strong>Ceph Manager 的引入</strong>，以及<strong>面向下一代硬件（NVMe、ARM）的性能重构</strong>。</p><p>从年初的密集性能优化，到年中 Luminous 版本的发布，再到年底对未来架构（DPDK/SPDK、C++ 协程、Crimson）的前瞻性讨论，2017 年完成了从&quot;让 BlueStore 可用&quot;到&quot;让 Ceph 面向未来&quot;的跨越。</p><hr><h2 id="二、重大里程碑" tabindex="-1">二、重大里程碑 <a class="header-anchor" href="#二、重大里程碑" aria-label="Permalink to &quot;二、重大里程碑&quot;">​</a></h2><h3 id="luminous-版本发布" tabindex="-1">Luminous 版本发布 <a class="header-anchor" href="#luminous-版本发布" aria-label="Permalink to &quot;Luminous 版本发布&quot;">​</a></h3><p>2017 年最重要的里程碑是 <strong>Luminous（v12）</strong> 版本的发布。根据 <a href="/VideoSummary/posts/2017/2017-AUG-02_-_-_Ceph_Developer_Monthly.html">2017-AUG-02 开发者月度会议</a>) 的记录，Luminous 在发布前进行了大量最终 bug 修复，并带来了以下重要特性 GA：</p><ul><li><strong>BlueStore</strong> 成为默认存储后端，取代 FileStore</li><li><strong>Ceph Manager（ceph-mgr）</strong> 正式引入，承担分析 API 和管理功能，使 Monitor 专注于关键集群状态</li><li>新的 <strong>Web Dashboard</strong>，提供集群监控和管理界面</li><li><strong>应用程序标签（Application Tags）</strong> 功能，允许对存储池打标签</li><li><strong>平衡器模块（Balancer Module）</strong>，支持数据均衡操作</li><li><strong>速率限制（Rate Limiting）</strong> 功能</li><li><strong>跨集群复制</strong> 和 <strong>共享读取缓存</strong> 功能</li><li>与 <strong>Prometheus</strong> 的集成</li></ul><p><a href="/VideoSummary/posts/2017/2017-JUN-07_-_-_Ceph_Developer_Monthly.html">2017-JUN-07 开发者月度会议</a>) 中还讨论了 Luminous 前的最后准备工作，包括存储池标签元数据设计和 OSD 部署工具（ceph-volume/LVM 方向）的简化。</p><hr><h2 id="三、核心组件年度进展" tabindex="-1">三、核心组件年度进展 <a class="header-anchor" href="#三、核心组件年度进展" aria-label="Permalink to &quot;三、核心组件年度进展&quot;">​</a></h2><h3 id="_3-1-bluestore" tabindex="-1">3.1 BlueStore <a class="header-anchor" href="#_3-1-bluestore" aria-label="Permalink to &quot;3.1 BlueStore&quot;">​</a></h3><p>BlueStore 是 2017 年投入最多的组件，贯穿全年的性能周会。主要进展包括：</p><p><strong>存储引擎优化</strong></p><ul><li>全年持续优化 RocksDB 配置，包括 column families、WAL 设置、compaction read-ahead 等，详见 <a href="/VideoSummary/posts/2017/2017-MAY-04_-_-_Ceph_Performance_Weekly.html">2017-MAY-04 性能周会</a>) 和 <a href="./2017-MAR-08_-_Ceph_Performance_Weekly.html">2017-MAR-08 性能周会</a></li><li>Bitmap 分配器优化，减少锁争用和内存占用</li><li>延迟写入（deferred write）路径优化，实现灵活批处理策略</li><li>BlueStore 启动速度优化，减少初始化时间</li></ul><p><strong>缓存管理</strong></p><ul><li>新增多个缓存池用于 BlueStore，提高数据可见性</li><li>调整 BlueStore Cache 与 RocksDB Cache 的协同配置，详见 <a href="./2017-JUN-08_-_Ceph_Performance_Weekly.html">2017-JUN-08 性能周会</a></li><li>自适应限流（adaptive throttle）机制，基于目标延迟动态调整</li></ul><p><strong>性能成果</strong></p><ul><li>相比 FileStore，大型对象写入性能提升约 2倍（<a href="./2017-FEB-22_-_Ceph_Performance_Weekly.html">2017-FEB-22 性能周会</a>）</li><li>小随机写入性能比 FileStore 快约 20-25%</li><li>Luminous 版本整体性能表现良好</li></ul><h3 id="_3-2-rados-osd" tabindex="-1">3.2 RADOS / OSD <a class="header-anchor" href="#_3-2-rados-osd" aria-label="Permalink to &quot;3.2 RADOS / OSD&quot;">​</a></h3><ul><li><strong>PG 重映射（PG Remapping）</strong> 功能实现，允许在 PG 已映射后重新映射以优化数据分布，详见 <a href="./2017-MAR-22_-_Ceph_Performance_Weekly.html">2017-MAR-22 性能周会</a></li><li><strong>Fast Dispatch</strong> 优化合并，减少 OSD 消息处理延迟</li><li><strong>PG 日志优化</strong>：<a href="./2017-NOV-01_-_Ceph_Developer_Monthly.html">2017-NOV-01 开发者月度会议</a> 讨论了在 SD 上使用环形缓冲区存储 PG 日志、FIFO 压缩模式，以减少写放大</li><li><strong>快照修剪（Snapshot Trimming）</strong> 优化，使用增量数据结构提高效率</li><li><strong>去重（Deduplication）</strong> 方案讨论，提出使用对象映射和内容地址存储池</li></ul><h3 id="_3-3-rgw-rados-gateway" tabindex="-1">3.3 RGW（RADOS Gateway） <a class="header-anchor" href="#_3-3-rgw-rados-gateway" aria-label="Permalink to &quot;3.3 RGW（RADOS Gateway）&quot;">​</a></h3><ul><li>全年持续进行 RGW 性能测试，NVMe 环境下网络成为瓶颈</li><li><strong>跨集群复制（Cross-cluster Replication）</strong> 功能进入 Luminous</li><li><strong>云同步（Cloud Sync）</strong> 功能开发，详见 <a href="./2017-DEC-06_-_Ceph_Developer_Monthly.html">2017-DEC-06 开发者月度会议</a></li><li>大数据分析集成方向：<a href="./2017-FEB-23_--Ceph_Tech_Talks_-_Big_Data_Analytics.html">2017-FEB-23 Tech Talk</a> 展示了通过 Luxio 加速 Spark 访问 Swift/RGW 存储，性能提升超 30 倍</li></ul><h3 id="_3-4-rbd-rados-block-device" tabindex="-1">3.4 RBD（RADOS Block Device） <a class="header-anchor" href="#_3-4-rbd-rados-block-device" aria-label="Permalink to &quot;3.4 RBD（RADOS Block Device）&quot;">​</a></h3><ul><li><strong>BD 持久缓存（Persistent Cache）</strong> 框架开发，<a href="/VideoSummary/posts/2017/2017-JUN-07_-_-_Ceph_Developer_Monthly.html">2017-JUN-07 开发者月度会议</a>) 讨论了基于日志存储的缓存架构</li><li>写回节流（writeback throttle）设置优化，平衡吞吐量与读延迟</li><li><strong>Commit Majority</strong> 功能（阿里巴巴团队贡献），提高平均延迟和延迟抖动表现，详见 <a href="./2017-MAY-11_-_Ceph_Performance_Weekly.html">2017-MAY-11 性能周会</a></li><li>异步恢复（async recovery）机制优化</li></ul><h3 id="_3-5-cephfs" tabindex="-1">3.5 CephFS <a class="header-anchor" href="#_3-5-cephfs" aria-label="Permalink to &quot;3.5 CephFS&quot;">​</a></h3><ul><li>全年 CephFS 相关讨论相对较少，主要集中在稳定性和 MDS 内存管理优化</li><li>跨数据中心复制的全局顺序维护方案讨论，详见 <a href="/VideoSummary/posts/2017/2017-SEP-06_-_-_Ceph_Developer_Monthly.html">2017-SEP-06 开发者月度会议</a>)</li></ul><h3 id="_3-6-ceph-manager-与-dashboard" tabindex="-1">3.6 Ceph Manager 与 Dashboard <a class="header-anchor" href="#_3-6-ceph-manager-与-dashboard" aria-label="Permalink to &quot;3.6 Ceph Manager 与 Dashboard&quot;">​</a></h3><p>Luminous 引入的 ceph-mgr 是 2017 年架构层面最重要的新增组件：</p><ul><li><a href="/VideoSummary/posts/2017/2017-APR-12_-_-_Ceph_Developer_Monthly.html">2017-APR-12 开发者月度会议</a>) 讨论了为 Manager 添加 REST API（作为实验性功能）</li><li>配置选项注释系统（config option annotations）设计，支持文档自动生成</li><li>新 Web Dashboard 提供集群状态可视化</li><li>服务映射（Service Map）功能，支持从命令行或模块访问服务信息</li></ul><h3 id="_3-7-网络层-messenger" tabindex="-1">3.7 网络层（Messenger） <a class="header-anchor" href="#_3-7-网络层-messenger" aria-label="Permalink to &quot;3.7 网络层（Messenger）&quot;">​</a></h3><ul><li><strong>Async Messenger</strong> 成为默认消息传递后端，全年持续优化锁争用问题</li><li><strong>RDMA 异步消息传递</strong> 开发推进，<a href="./2017-FEB-22_-_Ceph_Performance_Weekly.html">2017-FEB-22 性能周会</a> 记录了性能计数器和零拷贝代码的添加</li><li>零拷贝（zero-copy）优化工作持续推进</li></ul><hr><h2 id="四、社区生态" tabindex="-1">四、社区生态 <a class="header-anchor" href="#四、社区生态" aria-label="Permalink to &quot;四、社区生态&quot;">​</a></h2><h3 id="平台与部署工具" tabindex="-1">平台与部署工具 <a class="header-anchor" href="#平台与部署工具" aria-label="Permalink to &quot;平台与部署工具&quot;">​</a></h3><ul><li><strong>Ceph on ARM</strong> 专题 Tech Talk（<a href="/VideoSummary/posts/2017/2017-MAY-25_--_Ceph_Tech_Talk_-_Ceph_on_ARM.html">2017-MAY-25 Tech Talk</a>)）汇聚了 Red Hat、Cavium、SUSE、Deutsche Telekom、ARM 等多家公司，讨论 ARM64 平台的 CI/CD 建设和二进制发布</li><li><strong>Juju/Charm</strong> 部署工具（Canonical）展示了跨平台自动化部署能力，详见 <a href="./2017-MAR-23_--_Ceph_Tech_Talks_-_Ceph_at_Scale_Writing_Applicationswith_Language_Bindings.html">2017-MAR-23 Tech Talk</a></li><li><strong>Ceph Rust绑定</strong> 开发，为新语言生态提供支持</li></ul><h3 id="开发者社区" tabindex="-1">开发者社区 <a class="header-anchor" href="#开发者社区" aria-label="Permalink to &quot;开发者社区&quot;">​</a></h3><ul><li><a href="./2017-JAN-26_--_Ceph_Tech_Talk_-_Getting_Started_with_CephDevelopment.html">2017-JAN-26 Tech Talk</a> 专门面向新贡献者，介绍开发流程、构建环境和 PR 提交规范，体现社区对降低贡献门槛的重视</li><li>阿里巴巴团队深度参与性能优化，贡献了 Commit Majority、OST 性能优化等多项工作</li><li>Nokia 团队持续参与 BlueStore 测试，提供云 DVR 场景的真实负载反馈</li><li>CERN 部署了 200节点临时集群用于新代码测试</li></ul><h3 id="性能周会制度" tabindex="-1">性能周会制度 <a class="header-anchor" href="#性能周会制度" aria-label="Permalink to &quot;性能周会制度&quot;">​</a></h3><p>全年坚持每周性能会议（Ceph Performance Weekly），形成了高效的性能问题跟踪和 PR 审查机制，是 2017 年 BlueStore 快速成熟的重要保障。</p><hr><h2 id="五、下一年展望" tabindex="-1">五、下一年展望 <a class="header-anchor" href="#五、下一年展望" aria-label="Permalink to &quot;五、下一年展望&quot;">​</a></h2><p>基于 <a href="/VideoSummary/posts/2017/2017-DEC-06_-_-_Ceph_Developer_Monthly.html">2017-DEC-06 开发者月度会议</a>) 的路线图讨论，2018 年的技术方向已经清晰：</p><h3 id="性能重构-crimson-seastore-前身" tabindex="-1">性能重构（Crimson/SeaStore 前身） <a class="header-anchor" href="#性能重构-crimson-seastore-前身" aria-label="Permalink to &quot;性能重构（Crimson/SeaStore 前身）&quot;">​</a></h3><ul><li>采用 <strong>DPDK</strong> 和 <strong>SPDK</strong> 进行网络和存储 IO，绕过内核栈</li><li>对 OSD 进行大规模重构，使其更加<strong>模块化、异步和事件驱动</strong></li><li>探索使用 <strong>C++ 协程</strong>（Seastar 框架方向）重构 OSD，简化异步代码</li><li>减少数据结构和数据复制，提高 CPU 利用率</li></ul><h3 id="存储池多样化" tabindex="-1">存储池多样化 <a class="header-anchor" href="#存储池多样化" aria-label="Permalink to &quot;存储池多样化&quot;">​</a></h3><ul><li>非复制池（直接写入 SPDK）</li><li>并行写入多副本的池（不同一致性和容错模型）</li><li>适用于 NVMe-oF fabrics 的池</li></ul><h3 id="消息协议改进" tabindex="-1">消息协议改进 <a class="header-anchor" href="#消息协议改进" aria-label="Permalink to &quot;消息协议改进&quot;">​</a></h3><ul><li>新一代消息传递协议（msgr2），提高效率和安全性</li></ul><h3 id="运维与管理" tabindex="-1">运维与管理 <a class="header-anchor" href="#运维与管理" aria-label="Permalink to &quot;运维与管理&quot;">​</a></h3><ul><li>ceph-mgr 模块生态持续扩展</li><li>Dashboard 功能增强，向完整管理界面演进</li><li>统一 QoS（mClock 调度器）完善</li></ul><hr><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>2017 年，Ceph 以 <strong>Luminous 版本发布</strong>为核心里程碑，完成了 BlueStore 的生产就绪、ceph-mgr 的架构引入，以及 ARM/NVMe 等新硬件平台的适配。社区在保持高频迭代的同时，已开始为下一代架构（Crimson OSD、SPDK 集成）奠定基础。阿里巴巴、Nokia、CERN、Canonical 等生态伙伴的深度参与，标志着 Ceph 正从&quot;Red Hat 主导的项目&quot;向&quot;真正的多厂商开源社区&quot;演进。</p><hr><h2 id="参考文章" tabindex="-1">参考文章 <a class="header-anchor" href="#参考文章" aria-label="Permalink to &quot;参考文章&quot;">​</a></h2><ul><li><a href="/VideoSummary/posts/2017/2016-DEC-07_-_-_Ceph_Performance_Weekly.html">2016-DEC-07 :: Ceph Performance Weekly</a>)</li><li><a href="/VideoSummary/posts/2017/2016-DEC-14_-_-_Ceph_Performance_Weekly.html">2016-DEC-14 :: Ceph Performance Weekly</a>)</li><li><a href="/VideoSummary/posts/2017/2016-NOV-09_-_-_Ceph_Performance_Weekly.html">2016-NOV-09 :: Ceph Performance Weekly</a>)</li><li><a href="/VideoSummary/posts/2017/2016-NOV-16_-_-_Ceph_Performance_Weekly.html">2016-NOV-16 :: Ceph Performance Weekly</a>)</li><li><a href="/VideoSummary/posts/2017/2016-NOV-23_-_-_Ceph_Performance_Weekly.html">2016-NOV-23 :: Ceph Performance Weekly</a>)</li><li><a href="/VideoSummary/posts/2017/2016-OCT-12_-_-_Ceph_Performance_Weekly.html">2016-OCT-12 :: Ceph Performance Weekly</a>)</li><li><a href="/VideoSummary/posts/2017/2016-OCT-16_-_-_Ceph_Performance_Weekly.html">2016-OCT-16 :: Ceph Performance Weekly</a>)</li><li><a href="/VideoSummary/posts/2017/2016-SEP-07_-_-_Ceph_Performance_Weekly.html">2016-SEP-07 :: Ceph Performance Weekly</a>)</li><li><a href="/VideoSummary/posts/2017/2016-SEP-14_-_-_Ceph_Performance_Weekly.html">2016-SEP-14 :: Ceph Performance Weekly</a>)</li><li><a href="/VideoSummary/posts/2017/2016-SEP-21_-_-_Ceph_Performance_Weekly.html">2016-SEP-21 :: Ceph Performance Weekly</a>)</li><li><a href="/VideoSummary/posts/2017/2016-SEP-28_-_-_Ceph_Performance_Weekly.html">2016-SEP-28 :: Ceph Performance Weekly</a>)</li><li><a href="/VideoSummary/posts/2017/2017-APR-05_-_-_Ceph_Performance_Weekly.html">2017-APR-05 :: Ceph Performance Weekly</a>)</li><li><a href="/VideoSummary/posts/2017/2017-APR-12_-_-_Ceph_Developer_Monthly.html">2017-APR-12 :: Ceph Developer Monthly</a>)</li><li><a href="/VideoSummary/posts/2017/2017-APR-12_-_-_Ceph_Performance_Weekly.html">2017-APR-12 :: Ceph Performance Weekly</a>)</li><li><a href="/VideoSummary/posts/2017/2017-APR-27_-_-_Ceph_Performance_Weekly.html">2017-APR-27 :: Ceph Performance Weekly</a>)</li><li><a href="/VideoSummary/posts/2017/2017-AUG-02_-_-_Ceph_Developer_Monthly.html">2017-AUG-02 :: Ceph Developer Monthly</a>)</li><li><a href="/VideoSummary/posts/2017/2017-DEC-06_-_-_Ceph_Developer_Monthly.html">2017-DEC-06 :: Ceph Developer Monthly</a>)</li><li><a href="/VideoSummary/posts/2017/2017-FEB-01_-_-_Ceph_Performance_Weekly.html">2017-FEB-01 :: Ceph Performance Weekly</a>)</li><li><a href="/VideoSummary/posts/2017/2017-FEB-08_-_-_Ceph_Performance_Weekly.html">2017-FEB-08 :: Ceph Performance Weekly</a>)</li><li><a href="/VideoSummary/posts/2017/2017-FEB-15_-_-_Ceph_Performance_Weekly.html">2017-FEB-15 :: Ceph Performance Weekly</a>)</li><li><a href="/VideoSummary/posts/2017/2017-FEB-22_-_-_Ceph_Performance_Weekly.html">2017-FEB-22 :: Ceph Performance Weekly</a>)</li><li><a href="/VideoSummary/posts/2017/2017-FEB-23_--_Ceph_Tech_Talks_-_Big_Data_Analytics.html">2017-FEB-23 -- Ceph Tech Talks: Big Data Analytics</a>)</li><li><a href="/VideoSummary/posts/2017/2017-JAN-26_--_Ceph_Tech_Talk_-_Getting_Started_with_Ceph_Development.html">2017-JAN-26 -- Ceph Tech Talk: Getting Started with Ceph Development</a>)</li><li><a href="/VideoSummary/posts/2017/2017-JUN-01_-_-_Ceph_Performance_Weekly.html">2017-JUN-01 :: Ceph Performance Weekly</a>)</li><li><a href="/VideoSummary/posts/2017/2017-JUN-07_-_-_Ceph_Developer_Monthly.html">2017-JUN-07 :: Ceph Developer Monthly</a>)</li><li><a href="/VideoSummary/posts/2017/2017-JUN-08_-_-_Ceph_Performance_Weekly.html">2017-JUN-08 :: Ceph Performance Weekly</a>)</li><li><a href="/VideoSummary/posts/2017/2017-JUN-15_-_-_Ceph_Performance_Weekly.html">2017-JUN-15 :: Ceph Performance Weekly</a>)</li><li><a href="/VideoSummary/posts/2017/2017-MAR-01_-_-_Ceph_Performance_Weekly.html">2017-MAR-01 -- Ceph Performance Weekly</a>)</li><li><a href="/VideoSummary/posts/2017/2017-MAR-08_-_-_Ceph_Performance_Weekly.html">2017-MAR-08 :: Ceph Performance Weekly</a>)</li><li><a href="/VideoSummary/posts/2017/2017-MAR-22_-_-_Ceph_Performance_Weekly.html">2017-MAR-22 :: Ceph Performance Weekly</a>)</li><li><a href="/VideoSummary/posts/2017/2017-MAR-23_--_Ceph_Tech_Talks_-_Ceph_at_Scale_Writing_Applications_with_Language_Bindings.html">2017-MAR-23 -- Ceph Tech Talks: Ceph at Scale &amp; Writing Applications with Language Bindings</a>)</li><li><a href="/VideoSummary/posts/2017/2017-MAR-29_-_-_Ceph_Performance_Weekly.html">2017-MAR-29 :: Ceph Performance Weekly</a>)</li><li><a href="/VideoSummary/posts/2017/2017-MAY-04_-_-_Ceph_Performance_Weekly.html">2017-MAY-04 :: Ceph Performance Weekly</a>)</li><li><a href="/VideoSummary/posts/2017/2017-MAY-11_-_-_Ceph_Performance_Weekly.html">2017-MAY-11 :: Ceph Performance Weekly</a>)</li><li><a href="/VideoSummary/posts/2017/2017-MAY-18_-_-_Ceph_Performance_Weekly.html">2017-MAY-18 :: Ceph Performance Weekly</a>)</li><li><a href="/VideoSummary/posts/2017/2017-MAY-25_--_Ceph_Tech_Talk_-_Ceph_on_ARM.html">2017-MAY-25 -- Ceph Tech Talk: Ceph on ARM</a>)</li><li><a href="/VideoSummary/posts/2017/2017-MAY-25_-_-_Ceph_Performance_Weekly.html">2017-MAY-25 :: Ceph Performance Weekly</a>)</li><li><a href="/VideoSummary/posts/2017/2017-NOV-01_-_-_Ceph_Developer_Monthly.html">2017-NOV-01 :: Ceph Developer Monthly</a>)</li><li><a href="/VideoSummary/posts/2017/2017-SEP-06_-_-_Ceph_Developer_Monthly.html">2017-SEP-06 :: Ceph Developer Monthly</a>)</li><li><a href="/VideoSummary/posts/2017/Ceph_Promo_Video_2017.html">Ceph Promo Video 2017</a>)</li></ul>',59)])])}const u=a(i,[["render",h]]);export{c as __pageData,u as default};
